299	    @Test
300	    void rescheduleRejectsThirdPartySectionConflictAndRollsBack() throws Exception {
301	        String section = key("SEC");
302	        String thirdParty = key("SCH");
303	        createPlan(thirdParty, occ("G9", section, iso(10), iso(11)));
