package com.example.starter.plan.model;

import java.time.Instant;

/**
 * 区段封锁切换单。调度员登记区段与左闭右开 UTC 封锁窗口，
 * 登记后为 REGISTERED（可预览、可提交激活），激活成功后为 ACTIVE（终态，不可再次激活）。
 *
 * @param id          主键
 * @param switchKey   切换单业务键，全局唯一，登记后不可复用
 * @param sectionId   封锁区段 ID
 * @param startUtc    封锁窗口开始时刻（含），UTC
 * @param endUtc      封锁窗口结束时刻（不含），UTC，必须晚于 startUtc
 * @param status      切换单状态：REGISTERED 已登记 / ACTIVE 已激活
 * @param snapshotJson 激活成功后的完整切换快照（JSON）；登记态为 null，激活后不可变
 * @param createdAt   创建时刻，UTC 毫秒
 * @param updatedAt   最近变更时刻，UTC 毫秒
 */
public record SectionSwitch(long id, String switchKey, String sectionId, Instant startUtc,
                            Instant endUtc, SwitchStatus status, String snapshotJson,
                            long createdAt, long updatedAt) {
}

package com.example.starter.plan.model;

/**
 * 区段封锁切换单状态：REGISTERED 已登记待激活；ACTIVE 已激活（终态）。
 */
public enum SwitchStatus {
    REGISTERED,
    ACTIVE
}

package com.example.starter.plan.model;

/**
 * 封锁切换替代关联（不可变一对一）。激活提交时为每个被挂起的旧计划写入唯一旧→替代映射，
 * 一个旧计划最多被替代一次，一个替代计划最多替代一个旧计划，追加后不修改、不删除。
 * 与改签链（rail_plan_reschedule_link）相互独立，沿任一链环遍历时两者均不可成环。
 *
 * @param id                 主键
 * @param switchId           所属切换单 id，关联 rail_section_switch.id
 * @param oldPlanId          被挂起的旧计划 id，关联 rail_day_plan.id，全表唯一
 * @param replacementPlanId  替代旧计划的新计划 id，关联 rail_day_plan.id，全表唯一
 * @param createdAt          关联创建时刻，UTC 毫秒
 */
public record ReplacementLink(long id, long switchId, long oldPlanId, long replacementPlanId,
                              long createdAt) {
}

